<?php if(!defined('ABSPATH'))exit;get_header();$items=get_posts(['post_type'=>'qd_artifact','post_status'=>'publish','numberposts'=>100]);?><main class="qd-section"><div class="qd-shell"><nav class="qd-breadcrumb"><a href="<?php echo esc_url(home_url('/')); ?>">QuantDeus</a><span>/</span><span>Knowledge</span></nav><div class="qd-section-head"><div><span class="qd-kicker">Knowledge Graph</span><h1 class="qd-page-title">Документы, open artifacts и replication packages</h1></div><p>Знание связывается с evidence grade, horizon, pillar и replication path.</p></div><div class="qd-content-grid"><?php foreach($items as $a):$g=(string)get_post_meta($a->ID,'qd_evidence_grade',true);?><article class="qd-card"><span class="qd-evidence grade-<?php echo esc_attr(strtolower($g?:'unknown')); ?>">Artifact · <?php echo esc_html($g?:'UNKNOWN'); ?></span><h2><a href="<?php echo esc_url(get_permalink($a)); ?>"><?php echo esc_html(get_the_title($a)); ?></a></h2><p><?php echo esc_html(wp_trim_words(wp_strip_all_tags($a->post_content),30)); ?></p></article><?php endforeach;?></div></div></main><?php get_footer();?>